-- Table: hrm_overtime_detail
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_overtime_detail (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    overtime_id    BIGINT NOT NULL REFERENCES hrm_overtime(id) ON DELETE CASCADE,
    line_number    INTEGER NOT NULL CHECK (line_number > 0),
    overtime_date  DATE NOT NULL,
    start_time     TIME,
    end_time       TIME,
    hours          NUMERIC(9,2) NOT NULL DEFAULT 0 CHECK (hours >= 0),
    multiplier     NUMERIC(9,4) NOT NULL DEFAULT 1.5 CHECK (multiplier > 0),
    amount         NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (amount >= 0),
    notes          TEXT,
    UNIQUE (overtime_id, line_number)
);
